using UnityEngine;
using UnityEngine.UI;
using UnityEngine.Events;
using System.Collections.Generic;
using TMPro;

namespace GravityRoguelike.Combat
{
    /// <summary>
    /// Displays the choices generated by UpgradeManager and pauses the game
    /// until the player selects one.
    /// Uses Unity's built-in UI Button and legacy Text components.
    /// </summary>
    public class UpgradeSelectionUI : MonoBehaviour
    {
        [Header("References")]
        [SerializeField] private UpgradeManager upgradeManager;
        [SerializeField] private GameObject panel;
        [SerializeField] private Button[] choiceButtons = new Button[3];

        private readonly UnityAction[] buttonActions = new UnityAction[3];
        private float previousTimeScale = 1f;
        private bool isOpen;

        private void Awake()
        {
            if (panel != null)
                panel.SetActive(false);

            if (choiceButtons == null || choiceButtons.Length != 3)
                Debug.LogWarning("UpgradeSelectionUI: assign exactly three choice buttons.", this);
        }

        private void OnEnable()
        {
            if (upgradeManager == null)
            {
                Debug.LogError("UpgradeSelectionUI: assign an UpgradeManager.", this);
                return;
            }

            upgradeManager.ChoicesGenerated += ShowChoices;
        }

        private void OnDisable()
        {
            if (upgradeManager != null)
                upgradeManager.ChoicesGenerated -= ShowChoices;

            ClosePanel();
        }

        private void ShowChoices(IReadOnlyList<UpgradeDefinition> choices)
        {
            if (panel == null || choiceButtons == null)
            {
                Debug.LogError("UpgradeSelectionUI: assign the panel and choice buttons.", this);
                return;
            }

            if (choices.Count == 0)
            {
                ClosePanel();
                return;
            }

            for (int i = 0; i < choiceButtons.Length; i++)
            {
                Button button = choiceButtons[i];
                if (button == null) continue;

                // Remove only the listener this script added last time.
                if (buttonActions[i] != null)
                    button.onClick.RemoveListener(buttonActions[i]);

                bool hasChoice = i < choices.Count;
                button.gameObject.SetActive(hasChoice);
                if (!hasChoice) continue;

                UpgradeDefinition choice = choices[i];
                int nextLevel = upgradeManager.GetLevel(choice) + 1;

                TMP_Text label = button.GetComponentInChildren<TMP_Text>(true);
                if (label != null)
                {
                    label.text = $"{choice.UpgradeName}\n{choice.Description}\nLevel {nextLevel}/{choice.MaxLevel}";
                }

                UpgradeDefinition capturedChoice = choice;
                buttonActions[i] = () => SelectChoice(capturedChoice);
                button.onClick.AddListener(buttonActions[i]);
            }

            // Remember the time scale only on the first open. If new choices arrive while the panel is
            // already open, the time scale is 0 and saving it again would freeze the game after closing.
            if (!isOpen)
            {
                previousTimeScale = Time.timeScale;
                Time.timeScale = 0f;
            }
            isOpen = true;
            panel.SetActive(true);
        }

        private void SelectChoice(UpgradeDefinition choice)
        {
            if (upgradeManager != null && upgradeManager.TrySelectUpgrade(choice))
                ClosePanel();
        }

        private void ClosePanel()
        {
            if (panel != null)
                panel.SetActive(false);

            if (isOpen)
            {
                Time.timeScale = previousTimeScale;
                isOpen = false;
            }
        }
    }
}